
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_gdme_kos_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_gdme_kos", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.621242357724683e+01, 9.218369748257965e+00, 4.456365234049985e+00, 1.282724356369411e+00, -7.410870813213369e-01, -1.913467455448091e+00, -2.443816225433977e+00, -2.499099867495079e+00, -2.254612890667612e+00, -1.947062121400406e+00, -1.714222212202134e+00, -8.274005073143442e-01, -4.510783821783594e-01, -4.979046429268958e-01, -4.513062828598136e-01, -4.335220416587334e-01, -7.208939625568406e-01, -2.230884579854094e+00, -1.103808575725659e+01, -1.011011648527850e+02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


